import unittest
from candidate import is_simple_power

class TestIsSimplePower(unittest.TestCase):
    def test_is_simple_power_base_case_true(self):
        self.assertTrue(is_simple_power(1, 4))

    def test_is_simple_power_square_true(self):
        self.assertTrue(is_simple_power(2, 2))

    def test_is_simple_power_cube_true(self):
        self.assertTrue(is_simple_power(8, 2))

    def test_is_simple_power_false_base(self):
        self.assertFalse(is_simple_power(3, 2))

    def test_is_simple_power_false_exponent(self):
        self.assertFalse(is_simple_power(3, 1))

    def test_is_simple_power_false_base_and_exponent(self):
        self.assertFalse(is_simple_power(5, 3))

    def test_is_simple_power_zero_base(self):
        with self.assertRaises(ZeroDivisionError):
            is_simple_power(2, 0)

    def test_is_simple_power_negative_base(self):
        self.assertFalse(is_simple_power(2, -2))

    def test_is_simple_power_non_integer_base(self):
        self.assertFalse(is_simple_power(2, 2.5))

    def test_is_simple_power_non_integer_exponent(self):
        with self.assertRaises(TypeError):
            is_simple_power(2.5, 2)

    def test_is_simple_power_none_base(self):
        with self.assertRaises(TypeError):
            is_simple_power(None, 2)

    def test_is_simple_power_none_exponent(self):
        with self.assertRaises(TypeError):
            is_simple_power(2, None)

if __name__ == '__main__':
    unittest.main()
